/**
 * UNI-204: the scanner against real pi-session text (docs/m5/fixtures/
 * uni204-corpus.json, regenerated by docs/m5/uni204-audit.mts — one sample
 * per surface × path shape that had a file existing on the PC). Every
 * path that existed when sampled must still be a candidate.
 */
import { describe, expect, it } from 'vitest';
import corpus from '../../../../../docs/m5/fixtures/uni204-corpus.json';
import { scanFileRefs, type ScanMode } from './fileRefScan';

type Sample = { surface: string; mode: ScanMode; text: string; candidates: string[]; linked: string[] };

describe('real-session corpus (UNI-204)', () => {
  it('has samples for every surface the user asked about', () => {
    const surfaces = new Set((corpus as Sample[]).map((s) => s.surface.replace(/ \(.*\)$/, '')));
    for (const s of ['user message', 'assistant prose', 'assistant `inline code`', 'assistant ```fenced```', 'tool row subject', 'bash command', 'tool result: bash', 'tool result: grep', 'tool result: find/ls', 'tool result: edit/write']) {
      expect(surfaces, s).toContain(s);
    }
  });

  it.each((corpus as Sample[]).map((s, i) => [i, s.surface, s] as const))('#%i %s: every file that existed is found', (_i, _s, sample) => {
    const found = scanFileRefs(sample.text, sample.mode).map((c) => sample.text.slice(c.start, c.end));
    for (const l of sample.linked) expect(found).toContain(l);
  });
});
